  const validate=new Ajv({strict:true}).compile(schema);
  expect(validate(fixture)).toBe(true);
  for(const currency of ["copiedItems","copiedBytes","retainedCapacityBytes","releasedBytes"]){
    const omitted=structuredClone(fixture);delete omitted.expected.mixedProgress[currency];expect(validate(omitted)).toBe(false);
    const changed=structuredClone(fixture);changed.expected.mixedProgress[currency]=0;expect(validate(changed)).toBe(false);
  }
  const collapsed=structuredClone(fixture);collapsed.expected.mixedProgress.maximumBytes=96;expect(validate(collapsed)).toBe(false);
  const source=Buffer.alloc(fixture.sourceCapacityBytes);source[0]=fixture.payloadByte;
  const replacement=Buffer.alloc(fixture.replacementCapacityBytes);source.copy(replacement,0,0,1);
  const independent={copiedItems:1,copiedBytes:1,retainedCapacityBytes:replacement.byteLength,releasedBytes:source.byteLength};
  expect(replacement[0]).toBe(fixture.payloadByte);
  expect(stableStringify(independent)).toBe(stableStringify(fixture.expected.mixedProgress));
  const demand={copyBytes:1,capacityBytes:replacement.byteLength,releaseBytes:source.byteLength,depth:1+1};
  expect(stableStringify(demand)).toBe(stableStringify(fixture.expectedMixedDemand));
  for(const currency of ["copyBytes","capacityBytes","releaseBytes","depth"]){const omitted=structuredClone(fixture);delete omitted.expectedMixedDemand[currency];expect(validate(omitted)).toBe(false);}
  expect(stableStringify(fixture.deque.source)).toBe(fixture.deque.canonicalSource);
  for(const text of fixture.deque.source)expect(Buffer.byteLength(text)).toBeLessThan(fixture.deque.payloadCapacity);
  const missing=structuredClone(fixture);missing.deque.expectedMissingReleaseDemands=1;expect(validate(missing)).toBe(false);
  console.log("[DEBUG] original ordered mixed receipt strictAjv=true omittedCurrencies=4 invalidCurrencies=4 independentBufferCopy=true");
});

