        let guarded = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| match kind {
            0 => drop(map),
            1 => { let cursor = map.begin_set("next".into(), Payload(Arc::clone(&drops))); retire(map, Grant { maximum_items: 1, maximum_bytes: 1 }); drop(cursor); }
